html:
{%- import "erpnext/templates/print_formats/report_print_macros.html" as rp -%}
{%- set show_company = no_letterhead if no_letterhead is defined else not letter_head -%}
{%- set today = frappe.utils.today() -%}
{%- set rows = [] -%}
{%- for row in data if row is mapping and row.sales_order and not row.is_total_row and row.pending_qty > 0 -%}
	{%- set ignore = rows.append(row) -%}
{%- endfor -%}
{{ rp.styles() }}
<div class="rpf">
	{%- if show_company %}{{ rp.company_header(filters.company) }}{% endif %}
	{{ rp.head(_("Sales Orders Outstanding"), _("As on {0}").format(rp.date(today))) }}
	<table class="rpf-grid">
		<colgroup><col style="width: 84px"><col><col style="width: 64px"><col style="width: 70px"><col style="width: 90px"><col style="width: 84px"><col style="width: 76px"><col style="width: 114px"></colgroup>
		<thead>
			<tr>
				<th>{{ _("Date") }}</th>
				<th>{{ _("Item") }}</th>
				<th class="num">{{ _("Ordered") }}</th>
				<th class="num">{{ _("Delivered") }}</th>
				<th class="num">{{ _("Pending") }}</th>
				<th>{{ _("Deliver By") }}</th>
				<th class="num">{{ _("Overdue") }}</th>
				<th class="num">{{ _("Pending Value") }}</th>
			</tr>
		</thead>
		<tbody>
			{%- set last = namespace(order=None) %}
			{%- for row in rows %}
			{%- set overdue = frappe.utils.date_diff(today, row.delivery_date) if row.delivery_date else 0 %}
			{%- if row.sales_order != last.order %}
			<tr class="group">
				<td class="nowrap"><span class="regular">{{ rp.date(row.date) }}</span></td>
				<td colspan="6">{{ row.sales_order }} <span class="regular">· {{ row.customer }}</span></td>
				<td class="num">{{ rp.money(rows | selectattr("sales_order", "equalto", row.sales_order) | map(attribute="pending_amount") | map("float") | sum) }}</td>
			</tr>
			{%- set last.order = row.sales_order %}
			{%- endif %}
			<tr>
				<td></td>
				<td>{{ row.item_code }}</td>
				<td class="num muted">{{ rp.qty(row.qty) }}</td>
				<td class="num muted">{{ rp.qty(row.delivered_qty) }}</td>
				<td class="num">{{ rp.qty(row.pending_qty) }} <span class="muted">{{ row.uom or "" }}</span></td>
				<td class="nowrap">{{ rp.date(row.delivery_date) }}</td>
				<td class="num {{ 'danger' if overdue > 30 else '' }}">
					{%- if overdue > 0 %}{{ overdue }} {{ _("days") }}{% else %}<span class="muted">{{ _("Not due") }}</span>{% endif -%}
				</td>
				<td class="num">{{ rp.money(row.pending_amount) }}</td>
			</tr>
			{%- else %}
			<tr><td colspan="8" class="rpf-empty">{{ _("No pending orders") }}</td></tr>
			{%- endfor %}
			{%- if rows %}
			<tr class="total">
				<td colspan="7">{{ _("Total") }} · {{ (_("{0} order") if rows | map(attribute="sales_order") | unique | list | length == 1 else _("{0} orders")).format(rows | map(attribute="sales_order") | unique | list | length) }}</td>
				<td class="num"><span class="double">{{ rp.money(rows | map(attribute="pending_amount") | map("float") | sum) }}</span></td>
			</tr>
			{%- endif %}
		</tbody>
	</table>
	{{ rp.footnote() }}
</div>
